//! PKCS#12 and PEM keystore loading.
//!
//! Supports both legacy PKCS#12 (3DES/RC2, via the `p12` crate) and modern
//! PKCS#12 (PBES2+PBKDF2+AES-256-CBC, as generated by DevEco Studio), via
//! the `pkcs12` + `pkcs5` + `pkcs8` RustCrypto crates.

use crate::error::SignError;

/// A loaded signing key + certificate chain.
pub struct SigningKey {
    /// PKCS#8 DER-encoded private key.
    pub private_key_der: Vec<u8>,
    /// DER-encoded X.509 certificates, leaf first.
    pub cert_chain: Vec<Vec<u8>>,
}

impl SigningKey {
    /// Load from a PKCS#12 (.p12 / .pfx) file.
    ///
    /// Tries the modern PBES2/AES-256-CBC path first (DevEco Studio keys),
    /// then falls back to the legacy 3DES/RC2 path.
    ///
    /// `key_alias` is currently unused (neither parser filters by alias),
    /// but kept in the signature for API compatibility with the Java tool.
    pub fn from_pkcs12(
        p12_bytes: &[u8],
        store_password: &str,
        _key_alias: &str,
        key_password: &str,
    ) -> Result<Self, SignError> {
        // Try modern PBES2 path first (DevEco Studio / OpenSSL 3.x default).
        match Self::from_pkcs12_pbes2(p12_bytes, store_password, key_password) {
            Ok(k) => Ok(k),
            Err(e_modern) => {
                // Fall back to legacy p12 crate (3DES / RC2).
                Self::from_pkcs12_legacy(p12_bytes, key_password).map_err(|e_legacy| {
                    SignError::KeystoreParseError(format!(
                        "PKCS#12 parse failed (modern: {e_modern}; legacy: {e_legacy})"
                    ))
                })
            }
        }
    }

    // -----------------------------------------------------------------------
    // Modern path: PBES2 + PBKDF2 + AES-256-CBC (DevEco Studio default)
    // -----------------------------------------------------------------------

    fn from_pkcs12_pbes2(
        p12_bytes: &[u8],
        store_password: &str,
        key_password: &str,
    ) -> Result<Self, SignError> {
        use cms::encrypted_data::EncryptedData;
        use const_oid::ObjectIdentifier;
        use der::asn1::{ContextSpecific, OctetString};
        use der::{Decode, Encode};
        use pkcs12::authenticated_safe::AuthenticatedSafe;
        use pkcs12::cert_type::CertBag;
        use pkcs12::pfx::Pfx;
        use pkcs12::safe_bag::SafeContents;
        use pkcs8::EncryptedPrivateKeyInfo;

        // CMS content-type OIDs (RFC 5652).
        const ID_DATA: ObjectIdentifier = ObjectIdentifier::new_unwrap("1.2.840.113549.1.7.1");
        const ID_ENCRYPTED_DATA: ObjectIdentifier =
            ObjectIdentifier::new_unwrap("1.2.840.113549.1.7.6");

        // ── 1. Parse PFX ────────────────────────────────────────────────────
        let pfx = Pfx::from_der(p12_bytes)
            .map_err(|e| SignError::KeystoreParseError(format!("PFX DER parse: {e}")))?;

        // ── 2. Unwrap AuthenticatedSafe ──────────────────────────────────────
        // auth_safe.content is Any, which encodes as an OCTET STRING wrapping
        // the DER-encoded AuthenticatedSafe (SEQUENCE OF ContentInfo).
        let content_der = pfx
            .auth_safe
            .content
            .to_der()
            .map_err(|e| SignError::KeystoreParseError(format!("auth_safe to_der: {e}")))?;
        let auth_safe_os = OctetString::from_der(&content_der)
            .map_err(|e| SignError::KeystoreParseError(format!("auth_safe OctetString: {e}")))?;
        let auth_safes = AuthenticatedSafe::from_der(auth_safe_os.as_bytes())
            .map_err(|e| SignError::KeystoreParseError(format!("AuthenticatedSafe: {e}")))?;

        // ── 3. Walk ContentInfos ────────────────────────────────────────────
        let mut private_key_der: Option<Vec<u8>> = None;
        let mut cert_chain: Vec<Vec<u8>> = Vec::new();

        for content_info in &auth_safes {
            let safe_contents_bytes: Vec<u8>;

            if content_info.content_type == ID_DATA {
                // Plain safe bag — content is OCTET STRING(SafeContents)
                let os_der = content_info.content.to_der().map_err(|e| {
                    SignError::KeystoreParseError(format!("plain safe to_der: {e}"))
                })?;
                let os = OctetString::from_der(&os_der).map_err(|e| {
                    SignError::KeystoreParseError(format!("plain safe OctetString: {e}"))
                })?;
                safe_contents_bytes = os.as_bytes().to_vec();
            } else if content_info.content_type == ID_ENCRYPTED_DATA {
                // Encrypted safe bag — decrypt with PBES2 then parse SafeContents.
                let enc_der = content_info
                    .content
                    .to_der()
                    .map_err(|e| SignError::KeystoreParseError(format!("enc safe to_der: {e}")))?;
                let enc_data = EncryptedData::from_der(&enc_der).map_err(|e| {
                    SignError::KeystoreParseError(format!("EncryptedData parse: {e}"))
                })?;

                let params_der = enc_data
                    .enc_content_info
                    .content_enc_alg
                    .parameters
                    .as_ref()
                    .ok_or_else(|| {
                        SignError::KeystoreParseError("missing PBES2 parameters".into())
                    })?
                    .to_der()
                    .map_err(|e| {
                        SignError::KeystoreParseError(format!("PBES2 params to_der: {e}"))
                    })?;

                let enc_os = enc_data.enc_content_info.encrypted_content.ok_or_else(|| {
                    SignError::KeystoreParseError("missing encrypted content".into())
                })?;

                let original_ct = enc_os.as_bytes().to_vec();

                // Try store_password first; retry with key_password on failure.
                let decrypted = Self::pbes2_decrypt(&params_der, store_password, &original_ct)
                    .or_else(|_| Self::pbes2_decrypt(&params_der, key_password, &original_ct))
                    .map_err(|e| {
                        SignError::KeystoreParseError(format!("PBES2 decrypt (safe): {e}"))
                    })?;

                safe_contents_bytes = decrypted;
            } else {
                // Skip envelope types we don't handle.
                continue;
            }

            // ── 4. Parse SafeContents and collect key + certs ───────────────
            let safe_bags = SafeContents::from_der(&safe_contents_bytes)
                .map_err(|e| SignError::KeystoreParseError(format!("SafeContents parse: {e}")))?;

            for bag in safe_bags {
                match bag.bag_id {
                    pkcs12::PKCS_12_PKCS8_KEY_BAG_OID => {
                        // ShroudedKeyBag → [0] EXPLICIT EncryptedPrivateKeyInfo
                        let cs: ContextSpecific<EncryptedPrivateKeyInfo<'_>> =
                            ContextSpecific::from_der(&bag.bag_value).map_err(|e| {
                                SignError::KeystoreParseError(format!(
                                    "shrouded key bag parse: {e}"
                                ))
                            })?;
                        let mut ct = cs.value.encrypted_data.to_vec();
                        let pt = cs
                            .value
                            .encryption_algorithm
                            .decrypt_in_place(key_password, &mut ct)
                            .map_err(|e| {
                                SignError::KeystoreParseError(format!("key decrypt: {e}"))
                            })?;
                        if private_key_der.is_none() {
                            private_key_der = Some(pt.to_vec());
                        }
                    }
                    pkcs12::PKCS_12_KEY_BAG_OID => {
                        // Plain (unencrypted) PKCS#8 KeyBag
                        use pkcs12::safe_bag::PrivateKeyInfo;
                        let cs: ContextSpecific<PrivateKeyInfo> =
                            ContextSpecific::from_der(&bag.bag_value).map_err(|e| {
                                SignError::KeystoreParseError(format!("key bag parse: {e}"))
                            })?;
                        if private_key_der.is_none() {
                            let der = cs.value.to_der().map_err(|e| {
                                SignError::KeystoreParseError(format!("PrivateKeyInfo to_der: {e}"))
                            })?;
                            private_key_der = Some(der);
                        }
                    }
                    pkcs12::PKCS_12_CERT_BAG_OID => {
                        // CertBag → [0] EXPLICIT CertBag
                        let cs: ContextSpecific<CertBag> =
                            ContextSpecific::from_der(&bag.bag_value).map_err(|e| {
                                SignError::KeystoreParseError(format!("cert bag parse: {e}"))
                            })?;
                        cert_chain.push(cs.value.cert_value.as_bytes().to_vec());
                    }
                    _ => {} // skip unknown bag types
                }
            }
        }

        let private_key_der = private_key_der.ok_or(SignError::NoPrivateKey)?;
        if cert_chain.is_empty() {
            return Err(SignError::NoCertificate);
        }

        Ok(SigningKey {
            private_key_der,
            cert_chain,
        })
    }

    /// Decrypt a PBES2-encrypted blob using the algorithm identified in
    /// `params_der` (DER-encoded `AlgorithmIdentifier` parameters) and the
    /// given password.  Returns the plaintext as a new `Vec<u8>`.
    fn pbes2_decrypt(
        params_der: &[u8],
        password: &str,
        ciphertext: &[u8],
    ) -> Result<Vec<u8>, String> {
        use der::Decode;
        use pkcs5::EncryptionScheme;
        use pkcs8::pkcs5::pbes2;

        let params = pbes2::Parameters::from_der(params_der)
            .map_err(|e| format!("PBES2 params parse: {e}"))?;
        let scheme = EncryptionScheme::from(params);
        let mut ct = ciphertext.to_vec();
        let pt = scheme
            .decrypt_in_place(password, &mut ct)
            .map_err(|e| format!("decrypt_in_place: {e}"))?;
        Ok(pt.to_vec())
    }

    // -----------------------------------------------------------------------
    // Legacy path: 3DES / RC2 (via the `p12` crate)
    // -----------------------------------------------------------------------

    fn from_pkcs12_legacy(p12_bytes: &[u8], key_password: &str) -> Result<Self, SignError> {
        use p12::PFX;

        let pfx = PFX::parse(p12_bytes)
            .map_err(|e| SignError::KeystoreParseError(format!("legacy PKCS#12 parse: {e:?}")))?;

        let keys = pfx
            .key_bags(key_password)
            .map_err(|e| SignError::KeystoreParseError(format!("key bags: {e:?}")))?;
        if keys.is_empty() {
            return Err(SignError::NoPrivateKey);
        }
        let private_key_der = keys.into_iter().next().unwrap();

        let certs = pfx
            .cert_x509_bags(key_password)
            .map_err(|e| SignError::KeystoreParseError(format!("cert bags: {e:?}")))?;
        if certs.is_empty() {
            return Err(SignError::NoCertificate);
        }

        Ok(SigningKey {
            private_key_der,
            cert_chain: certs,
        })
    }

    // -----------------------------------------------------------------------
    // PEM path
    // -----------------------------------------------------------------------

    /// Load from a separate PEM private key + PEM certificate.
    ///
    /// The PEM private key must be PKCS#8 (`BEGIN PRIVATE KEY`) format.
    /// The PEM certificate must be X.509 (`BEGIN CERTIFICATE`) format.
    pub fn from_pem(private_key_pem: &str, cert_pem: &str) -> Result<Self, SignError> {
        let private_key_der = Self::pkcs8_der_from_pem(private_key_pem)?;
        let cert_der = Self::cert_der_from_pem(cert_pem)?;

        Ok(SigningKey {
            private_key_der,
            cert_chain: vec![cert_der],
        })
    }

    /// Extract PKCS#8 DER bytes from a PEM-encoded private key string.
    fn pkcs8_der_from_pem(pem: &str) -> Result<Vec<u8>, SignError> {
        let pem = pem.trim();
        let b64 = pem
            .lines()
            .filter(|l| !l.starts_with("-----"))
            .collect::<Vec<_>>()
            .join("");
        base64_decode(&b64).map_err(|e| SignError::PemError(format!("base64 decode: {e}")))
    }

    /// Extract DER bytes from a PEM-encoded certificate string.
    fn cert_der_from_pem(pem: &str) -> Result<Vec<u8>, SignError> {
        let pem = pem.trim();
        let b64 = pem
            .lines()
            .filter(|l| !l.starts_with("-----"))
            .collect::<Vec<_>>()
            .join("");
        base64_decode(&b64).map_err(|e| SignError::PemError(format!("base64 decode: {e}")))
    }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;

    // ── Error cases ─────────────────────────────────────────────────────────

    #[test]
    fn test_empty_bytes_returns_err() {
        let result = SigningKey::from_pkcs12(&[], "", "key", "password");
        assert!(result.is_err(), "empty bytes must return Err, not panic");
    }

    #[test]
    fn test_random_bytes_returns_err() {
        let junk = b"this is definitely not a valid PKCS#12 file!";
        let result = SigningKey::from_pkcs12(junk, "pass", "key", "pass");
        assert!(result.is_err(), "random bytes must return Err");
    }

    #[test]
    fn test_wrong_password_returns_err() {
        let p12_path =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/test.p12");
        if !p12_path.exists() {
            eprintln!("SKIP: test P12 fixture not found at {:?}", p12_path);
            return;
        }
        let p12_bytes = std::fs::read(&p12_path).expect("read test.p12");
        let result = SigningKey::from_pkcs12(&p12_bytes, "wrong", "key", "wrong_password");
        assert!(result.is_err(), "wrong password must return Err");
    }

    /// Load the generated test PKCS#12 fixture (password: `test123`).
    ///
    /// This test requires the fixture file at
    /// `crates/arkdown-sign/tests/fixtures/test.p12`, generated by:
    /// ```bash
    /// openssl req -x509 -newkey rsa:2048 -keyout /tmp/key.pem -out /tmp/cert.pem \
    ///     -days 3650 -nodes -subj '/CN=test'
    /// openssl pkcs12 -export -out crates/arkdown-sign/tests/fixtures/test.p12 \
    ///     -inkey /tmp/key.pem -in /tmp/cert.pem -passout pass:test123
    /// ```
    #[test]
    fn test_load_rsa_p12_fixture() {
        let p12_path =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/test.p12");
        if !p12_path.exists() {
            eprintln!("SKIP: test P12 fixture not found at {:?}", p12_path);
            return;
        }
        let p12_bytes = std::fs::read(&p12_path).expect("read test.p12");
        let result = SigningKey::from_pkcs12(&p12_bytes, "test123", "1", "test123");
        assert!(
            result.is_ok(),
            "loading valid RSA P12 with correct password must succeed: {:?}",
            result.err()
        );
        let key = result.unwrap();
        assert!(
            !key.private_key_der.is_empty(),
            "private key DER must not be empty"
        );
        assert!(
            !key.cert_chain.is_empty(),
            "certificate chain must not be empty"
        );
        assert!(
            !key.cert_chain[0].is_empty(),
            "leaf certificate DER must not be empty"
        );
    }

    /// Load a DevEco Studio-generated PKCS#12 (PBES2+PBKDF2+AES-256-CBC).
    ///
    /// Skipped when the fixture path does not exist on disk so CI is not broken.
    #[test]
    #[ignore = "requires ~/.ohos/config signing materials on disk"]
    fn test_load_deveco_pbes2_p12() {
        let p12_path = "/Users/ranger/.ohos/config/default_minimal-hap_YwKQ1z12UQE8RNArp0QtmNHBdgynkTMsX5TAEv24uWE=.p12";
        let password = "BLvkWvzSyG4"; // decrypted from DevEco format
        if !std::path::Path::new(p12_path).exists() {
            return;
        }
        let p12_bytes = std::fs::read(p12_path).unwrap();
        let key = SigningKey::from_pkcs12(&p12_bytes, password, "debugKey", password)
            .expect("should load PBES2 p12");
        assert!(!key.private_key_der.is_empty());
        assert!(!key.cert_chain.is_empty());
    }

    // ── from_pem: base64 decoder ─────────────────────────────────────────────

    /// Test that `from_pem` with invalid base64 returns Err without panicking.
    #[test]
    fn test_from_pem_invalid_base64_returns_err() {
        let bad_key = "-----BEGIN PRIVATE KEY-----\n!!!not base64!!!\n-----END PRIVATE KEY-----";
        let bad_cert = "-----BEGIN CERTIFICATE-----\n!!!not base64!!!\n-----END CERTIFICATE-----";
        let result = SigningKey::from_pem(bad_key, bad_cert);
        assert!(result.is_err(), "invalid PEM base64 must return Err");
    }

    /// Test that empty PEM blocks return Err (no DER bytes to parse).
    #[test]
    fn test_from_pem_empty_content_returns_err_or_ok_with_empty_key() {
        let empty_key = "-----BEGIN PRIVATE KEY-----\n-----END PRIVATE KEY-----";
        let empty_cert = "-----BEGIN CERTIFICATE-----\n-----END CERTIFICATE-----";
        // Empty PEM may produce Ok or Err — no panic is the requirement.
        let result = SigningKey::from_pem(empty_key, empty_cert);
        let _ = result;
    }

    /// Verify the base64 decoder handles padding correctly.
    #[test]
    fn test_base64_decode_known_vector() {
        let encoded = "aGVsbG8=";
        let pem = format!("-----BEGIN PRIVATE KEY-----\n{encoded}\n-----END PRIVATE KEY-----");
        let cert_pem = "-----BEGIN CERTIFICATE-----\naGVsbG8=\n-----END CERTIFICATE-----";
        let result = SigningKey::from_pem(&pem, cert_pem);
        // Result will be Err(PemError) because "hello" is not valid PKCS#8,
        // but the error must NOT be from base64 decode.
        match &result {
            Err(crate::error::SignError::PemError(msg)) => {
                assert!(
                    !msg.contains("base64 decode"),
                    "base64 decode of 'aGVsbG8=' must succeed; got PemError: {msg}"
                );
            }
            _ => {}
        }
    }
}

/// Minimal base64 decoder (standard alphabet).
fn base64_decode(input: &str) -> Result<Vec<u8>, String> {
    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

    let mut lookup = [0xFFu8; 256];
    for (i, &c) in TABLE.iter().enumerate() {
        lookup[c as usize] = i as u8;
    }

    let bytes: Vec<u8> = input
        .bytes()
        .filter(|&b| b != b'\n' && b != b'\r' && b != b' ')
        .collect();

    let mut output = Vec::with_capacity((bytes.len() * 3) / 4);
    let mut i = 0;
    while i < bytes.len() {
        let b0 = bytes.get(i).copied().unwrap_or(b'=');
        let b1 = bytes.get(i + 1).copied().unwrap_or(b'=');
        let b2 = bytes.get(i + 2).copied().unwrap_or(b'=');
        let b3 = bytes.get(i + 3).copied().unwrap_or(b'=');

        let v0 = if b0 == b'=' { 0u8 } else { lookup[b0 as usize] };
        let v1 = if b1 == b'=' { 0u8 } else { lookup[b1 as usize] };
        let v2 = if b2 == b'=' { 0u8 } else { lookup[b2 as usize] };
        let v3 = if b3 == b'=' { 0u8 } else { lookup[b3 as usize] };

        if v0 == 0xFF || v1 == 0xFF {
            return Err(format!("invalid base64 char at position {i}"));
        }

        output.push((v0 << 2) | (v1 >> 4));
        if b2 != b'=' {
            if v2 == 0xFF {
                return Err(format!("invalid base64 char at position {}", i + 2));
            }
            output.push((v1 << 4) | (v2 >> 2));
        }
        if b3 != b'=' {
            if v3 == 0xFF {
                return Err(format!("invalid base64 char at position {}", i + 3));
            }
            output.push((v2 << 6) | v3);
        }
        i += 4;
    }
    Ok(output)
}
